sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?album ?releaseDate WHERE {
  VALUES ?album { dbr:Los_Monsters dbr:Wake_of_the_Flood }
  OPTIONAL { ?album dbp:released ?released . }
  OPTIONAL { ?album dbp:year ?year . }
  OPTIONAL { ?album dbp:nextYear ?nextYear . }
  BIND (COALESCE(?released, ?year, ?nextYear) AS ?releaseDate)
}
LIMIT 100

